// src/modes/learning/Learning.view.js
import { createElement, clear } from '@utils/dom';
import { renderGrid, attachGridEvents } from '@components/common/Grid';

const ACTIVITIES = [
  { id: 'quiz', label: 'Викторина', icon: '🧠' },
