// src/modes/learning/math/Math.controller.js
import { startActivity } from '@modes/common/activities';
import { generateMathQuestions } from './Math.logic';
import { renderMathGame } from './Math.view';

export function startMath(container, profile, settings, onBack, savedState) {
  startActivity({
    container,
    profile,
    settings,
    activityType: 'math',
    generateData: (prof, set) => generateMathQuestions(set),
    renderItem: (container, question, current, total, onAnswer, feedback, isCorrect, userAnswer) => {
      renderMathGame(container, {
        question,
        current,
        total,
        onAnswer,
        feedback,
        isCorrect,
        userAnswer,
        inputMethod: settings.inputMethod || 'drag',
      });
    },
    handleAnswer: (answer, question) => {
      const correct = answer === question.answer;
      return {
        correct,
        feedback: correct ? 'Верно!' : `Не верно, ответ: ${question.answer}`,
        details: {
          question: `${question.a} ${question.operator} ${question.b} = ?`,
          userAnswer: String(answer),
          correctAnswer: String(question.answer),
        },
      };
    },
    savedState,
    onBack,
  });
}

Math.logic.js.content:
// src/modes/learning/math/Math.logic.js
import { shuffle } from '@utils/array';

export function generateMathQuestions(settings) {
  const { operations, maxNumber, numQuestions, numOptions } = settings;
  // operations - объект { add: true, subtract: true, multiply: false, divide: false }
  const ops = [];
  if (operations.add) ops.push('+');
  if (operations.subtract) ops.push('-');
  if (operations.multiply) ops.push('*');
  if (operations.divide) ops.push('/');
  if (ops.length === 0) return [];

  const questions = [];
  for (let i = 0; i < numQuestions; i++) {
    const op = ops[Math.floor(Math.random() * ops.length)];
    let a, b, answer;
    switch (op) {
      case '+':
        a = randInt(1, maxNumber);
        b = randInt(1, maxNumber - a);
        answer = a + b;
        break;
      case '-':
        a = randInt(1, maxNumber);
        b = randInt(1, a);
        answer = a - b;
        break;
      case '*':
        a = randInt(1, Math.floor(maxNumber / 2));
        b = randInt(1, Math.floor(maxNumber / a));
        answer = a * b;
        break;
      case '/':
        b = randInt(1, Math.floor(maxNumber / 2));
        answer = randInt(1, Math.floor(maxNumber / b));
        a = b * answer;
        break;
      default: continue;
    }

    let options = [answer];
    let attempts = 0;
    while (options.length < numOptions && attempts < 100) {
      const offset = randInt(1, Math.max(3, Math.floor(maxNumber / 2)));
      const candidate = answer + (Math.random() > 0.5 ? offset : -offset);
      if (candidate >= 0 && !options.includes(candidate)) {
        options.push(candidate);
      }
      attempts++;
    }
    while (options.length < numOptions) {
      const candidate = randInt(0, maxNumber * 2);
      if (!options.includes(candidate)) options.push(candidate);
    }
    options = shuffle(options);

    const opSymbol = op === '+' ? '+' : op === '-' ? '-' : op === '*' ? '×' : '÷';
    questions.push({ a, b, operator: opSymbol, answer, options });
  }
  return questions;
}

function randInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

