// src/services/backup/export.js
import JSZip from 'jszip';
import { EXPORT_COMPONENTS } from './registry';
import { loadImage } from '@storage/imageStorage';  // ← было getImage, исправлено на loadImage
import { toast } from '@utils/toast';
import { logger } from '@utils/logger';
import { getActiveProfile } from '@state/actions';
import { getState } from '@state/store';

export async function exportToZip(selectedKeys, selectedCategoryIds = null) {
  const profile = getActiveProfile();
  const state = getState();
  const globalData = state.globalSettings || {};

  if (!profile) {
    toast('Нет активного профиля', 'error');
    return;
  }

  const zip = new JSZip();
  const manifest = {
    version: '2.0',
    date: new Date().toISOString(),
    components: {}
  };
  const allImageIds = new Set();
  const exportData = {};

  for (const key of selectedKeys) {
    const comp = EXPORT_COMPONENTS[key];
    if (!comp) continue;
    try {
      const result = await comp.export(profile, globalData);

      if (key === 'categories' && selectedCategoryIds && selectedCategoryIds.length > 0) {
        const filteredCats = result.data.categories.filter(c => selectedCategoryIds.includes(c.id));
        const filteredCards = {};
        filteredCats.forEach(cat => {
          filteredCards[cat.id] = (result.data.cards[cat.id] || []).slice();
        });
        result.data = { categories: filteredCats, cards: filteredCards };
        const ids = new Set();
        Object.values(filteredCards).forEach(arr => arr.forEach(c => c.imageId && ids.add(c.imageId)));
        result.imageIds = ids;
      }

      exportData[key] = result.data;
      result.imageIds.forEach(id => allImageIds.add(id));
      manifest.components[key] = true;
    } catch (e) {
      logger.error(`Ошибка экспорта компонента ${key}:`, e);
      toast(`Ошибка экспорта ${comp.label}`, 'error');
    }
  }

  zip.file('manifest.json', JSON.stringify(manifest, null, 2));
  for (const key in exportData) {
    zip.file(`${key}.json`, JSON.stringify(exportData[key], null, 2));
  }

  const imgFolder = zip.folder('images');
  for (const id of allImageIds) {
    try {
      const blob = await loadImage(id);  // ← здесь была getImage, исправлено
      if (blob) imgFolder.file(id, blob);
    } catch (e) {
      logger.warn(`Не удалось загрузить изображение ${id} для экспорта`, e);
    }
  }

  const blob = await zip.generateAsync({ type: 'blob' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `RAS_backup_${new Date().toISOString().slice(0,10)}.rasbackup`;
  a.click();
  toast('Экспорт завершён', 'success');
}

import.js.content:
// src/services/backup/import.js
import JSZip from 'jszip';
import { EXPORT_COMPONENTS } from './registry';
import { saveImage } from '@storage/imageStorage';  // ← есть, правильно
import { toast } from '@utils/toast';
import { logger } from '@utils/logger';
import { getActiveProfile } from '@state/actions';
import { getState, setState } from '@state/store';
import { saveProfile, saveAppData } from '@storage/appStorage';
import { openImportDialog } from '@modes/general/components/ImportDialog';

export async function importFromZip(file) {
  try {
    const zip = await JSZip.loadAsync(file);

    const manifestFile = zip.file('manifest.json');
    if (!manifestFile) {
      toast('Неверный формат: отсутствует manifest.json', 'error');
      throw new Error('Неверный формат: отсутствует manifest.json');
    }
    const manifestText = await manifestFile.async('string');
    const manifest = JSON.parse(manifestText);

    if (manifest.version !== '2.0') {
      toast('Неизвестная версия файла', 'error');
      throw new Error('Неизвестная версия файла');
    }

    const importedData = {};
    for (const key of Object.keys(manifest.components)) {
      const fileObj = zip.file(`${key}.json`);
      if (fileObj) {
        const text = await fileObj.async('string');
        importedData[key] = JSON.parse(text);
      }
    }

    const imgFolder = zip.folder('images');
    if (imgFolder) {
      const promises = [];
      imgFolder.forEach((relativePath, file) => {
        promises.push(file.async('blob').then(blob => saveImage(relativePath, blob)));
      });
      await Promise.all(promises);
    }

    openImportDialog(importedData, manifest, (selectedKeys, strategy, selectedCategories) => {
      applyImport(importedData, selectedKeys, strategy, selectedCategories);
    });

  } catch (err) {
    toast('Ошибка импорта: ' + err.message, 'error');
    logger.error('Импорт не удался', err);
  }
}

async function applyImport(importedData, selectedKeys, strategy, selectedCategoryIds) {
  const profile = getActiveProfile();
  const state = getState();
  const globalData = state.globalSettings || {};

  for (const key of selectedKeys) {
    const comp = EXPORT_COMPONENTS[key];
    if (!comp) continue;
    const data = importedData[key];
    if (!data) {
      logger.warn(`Данные для компонента ${key} отсутствуют в архиве`);
      continue;
    }
    try {
      if (key === 'categories' && selectedCategoryIds) {
        const filteredCats = data.categories.filter(c => selectedCategoryIds.includes(c.id));
        const filteredCards = {};
        filteredCats.forEach(cat => {
          filteredCards[cat.id] = data.cards[cat.id] || [];
        });
        await comp.import(profile, { categories: filteredCats, cards: filteredCards }, strategy);
      } else {
        await comp.import(profile, data, strategy, globalData);
      }
    } catch (e) {
      toast(`Ошибка импорта ${comp.label}: ${e.message}`, 'error');
      logger.error(`Ошибка импорта ${key}`, e);
    }
  }

  await saveProfile(profile);
  await saveAppData({ ...state, globalSettings: globalData });
  setState({ profiles: state.profiles, globalSettings: globalData });
  toast('Импорт завершён', 'success');
  // Перерендерим приложение
  import('@app/render').then(({ renderApp }) => renderApp());
}

registry.js.content:
// src/services/backup/registry.js
import { uid } from '@utils/id';

export const EXPORT_COMPONENTS = {
  categories: {
    label: 'Категории и карточки',
    export: async (profile) => {
      const categories = profile.categories || [];
      const cards = profile.cards || {};
      const imageIds = new Set();
      Object.values(cards).forEach(arr => arr.forEach(c => c.imageId && imageIds.add(c.imageId)));
      return { data: { categories, cards }, imageIds };
    },
    import: async (profile, data, strategy) => {
      const importedCats = data.categories || [];
      const importedCards = data.cards || {};
      if (strategy === 'overwrite') {
        profile.categories = importedCats.map(c => ({ ...c, id: uid() }));
        profile.cards = {};
        importedCats.forEach(cat => {
          const oldId = cat.id;
          const newCat = profile.categories.find(c => c.name === cat.name);
          if (newCat) {
            profile.cards[newCat.id] = (importedCards[oldId] || []).map(c => ({ ...c, id: uid() }));
          }
        });
      } else if (strategy === 'add') {
        importedCats.forEach(impCat => {
          const existing = profile.categories.find(c => c.name === impCat.name);
          if (!existing) {
            const newCat = { ...impCat, id: uid() };
            profile.categories.push(newCat);
            profile.cards[newCat.id] = (importedCards[impCat.id] || []).map(c => ({ ...c, id: uid() }));
          }
        });
      } else if (strategy === 'update') {
        importedCats.forEach(impCat => {
          const existing = profile.categories.find(c => c.name === impCat.name);
          if (existing) {
            profile.cards[existing.id] = (importedCards[impCat.id] || []).map(c => ({ ...c, id: uid() }));
          } else {
            const newCat = { ...impCat, id: uid() };
            profile.categories.push(newCat);
            profile.cards[newCat.id] = (importedCards[impCat.id] || []).map(c => ({ ...c, id: uid() }));
          }
        });
      }
    }
  },

  quick: {
    label: 'Быстрые кнопки',
    export: async (profile) => {
      const data = profile.quickButtons || [];
      const imageIds = new Set(data.filter(b => b.imageId).map(b => b.imageId));
      return { data, imageIds };
    },
    import: async (profile, data, strategy) => {
      const imported = data || [];
      if (strategy === 'overwrite' || strategy === 'update') {
        profile.quickButtons = imported.map(b => ({ ...b, id: uid() }));
      } else if (strategy === 'add') {
        profile.quickButtons.push(...imported.map(b => ({ ...b, id: uid() })));
      }
    }
  },

  yesno: {
    label: 'Да / Нет',
    export: async (profile) => {
      const data = profile.yesnoButtons || [];
      const imageIds = new Set(data.filter(b => b.imageId).map(b => b.imageId));
      return { data, imageIds };
    },
    import: async (profile, data, strategy) => {
      const imported = data || [];
      if (strategy === 'overwrite' || strategy === 'update') {
        profile.yesnoButtons = imported.map(b => ({ ...b, id: uid() }));
      } else if (strategy === 'add') {
        profile.yesnoButtons.push(...imported.map(b => ({ ...b, id: uid() })));
      }
    }
  },

  schedule: {
    label: 'Расписание',
    export: async (profile) => {
      const data = {
        templates: profile.scheduleTemplates || [],
        dayMapping: profile.scheduleDayMapping || {},
        dailyState: profile.scheduleDailyState || {}
      };
      const imageIds = new Set();
      data.templates.forEach(t => t.events.forEach(e => e.imageId && imageIds.add(e.imageId)));
      return { data, imageIds };
    },
    import: async (profile, data, strategy) => {
      const { templates, dayMapping, dailyState } = data;
      if (strategy === 'overwrite') {
        profile.scheduleTemplates = templates.map(t => ({
          ...t,
          id: uid(),
          events: t.events.map(e => ({ ...e, id: uid() }))
        }));
        profile.scheduleDayMapping = dayMapping;
        profile.scheduleDailyState = dailyState;
      } else if (strategy === 'add') {
        templates.forEach(t => {
          const exists = profile.scheduleTemplates.some(ex => ex.name === t.name);
          if (!exists) {
            profile.scheduleTemplates.push({
              ...t,
              id: uid(),
              events: t.events.map(e => ({ ...e, id: uid() }))
            });
          }
        });
        for (const day in dayMapping) {
          if (!profile.scheduleDayMapping[day]) {
            profile.scheduleDayMapping[day] = dayMapping[day];
          }
        }
        for (const date in dailyState) {
          if (!profile.scheduleDailyState[date]) {
            profile.scheduleDailyState[date] = dailyState[date];
          }
        }
      } else if (strategy === 'update') {
        templates.forEach(t => {
          const existing = profile.scheduleTemplates.find(ex => ex.name === t.name);
          if (existing) {
            existing.events = t.events.map(e => ({ ...e, id: uid() }));
          } else {
            profile.scheduleTemplates.push({
              ...t,
              id: uid(),
              events: t.events.map(e => ({ ...e, id: uid() }))
            });
          }
        });
        profile.scheduleDayMapping = dayMapping;
        profile.scheduleDailyState = dailyState;
      }
    }
  },

  settings: {
    label: 'Настройки (полноэкран, автосклонение, скрытые режимы)',
    export: async (profile, globalData) => {
      return {
        data: {
          fullscreen: globalData.fullscreen || false,
          autoInflect: globalData.autoInflect !== undefined ? globalData.autoInflect : true,
          hiddenModes: profile.hiddenModes || []   // ← теперь берём из профиля
        },
        imageIds: new Set()
      };
    },
    import: async (profile, data, strategy, globalData) => {
      if (data.fullscreen !== undefined) globalData.fullscreen = data.fullscreen;
      if (data.autoInflect !== undefined) globalData.autoInflect = data.autoInflect;
      if (data.hiddenModes !== undefined) profile.hiddenModes = data.hiddenModes;
    }
  },

  gameSettings: {
    label: 'Настройки игр',
    export: async (profile) => {
      const data = profile.gamesSettings || {};
      return { data, imageIds: new Set() };
    },
    import: async (profile, data, strategy) => {
      if (strategy === 'overwrite' || strategy === 'update') {
        profile.gamesSettings = data;
      } else if (strategy === 'add') {
        const current = profile.gamesSettings || {};
        for (const key in data) {
          if (!(key in current)) current[key] = data[key];
        }
        profile.gamesSettings = current;
      }
    }
  },

  learningSettings: {
    label: 'Настройки обучения',
    export: async (profile) => {
      const data = profile.learningSettings || {};
      return { data, imageIds: new Set() };
    },
    import: async (profile, data, strategy) => {
      if (strategy === 'overwrite' || strategy === 'update') {
        profile.learningSettings = data;
      } else if (strategy === 'add') {
        const current = profile.learningSettings || {};
        for (const key in data) {
          if (!(key in current)) current[key] = data[key];
        }
        profile.learningSettings = current;
      }
    }
  }
};

