settings.css.content:
/* Общие настройки */
.settings-mode {
  padding: var(--spacing-md);
}
.setting-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-sm) 0;
  border-bottom: 1px solid var(--border);
}
.setting-row:last-child {
  border-bottom: none;
}
.setting-row .toggle-switch {
  flex-shrink: 0;
}
.mode-order-chip {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm) var(--spacing-md);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  margin-bottom: var(--spacing-xs);
  cursor: grab;
  transition: opacity 0.2s, background 0.2s;
}
.mode-order-chip .mode-name {
  flex: 1;
}
.mode-order-chip .cursor-grab {
  cursor: grab;
  opacity: 0.6;
}
.mode-order-chip--hidden {
  opacity: 0.5;
  background: #f1f3f5;
}
.mode-order-chip--hidden .mode-name {
  text-decoration: line-through;
  color: var(--text-muted);
}

reset.css.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
input, textarea, select { user-select: text; }

html, body {
  height: 100%;                /* fallback */
  height: 100dvh;              /* динамическая высота (современные браузеры) */
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

#app {
  display: flex;
  flex-direction: column;
  height: 100%;
  height: 100dvh;
  overflow: hidden;
}

variables.css.content:
:root {
  --primary: #4caf50;
  --primary-dark: #388e3c;
  --primary-light: #a5d6a7;
  --danger: #c62828;
  --bg: #f0f2f5;
  --surface: #ffffff;
  --border: #d0d7de;
  --text: #1a1a1a;
  --text-secondary: #495057;
  --text-muted: #868e96;
  --radius: 16px;
  --radius-sm: 10px;
  --shadow: 0 2px 8px rgba(0,0,0,0.08);
  --font: 'Segoe UI', Roboto, system-ui, sans-serif, 'Segoe UI Emoji', 'Apple Color Emoji', 'Noto Color Emoji';  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 12px;
  --spacing-lg: 16px;
  --spacing-xl: 24px;
  --transition: 0.2s ease;

.tile-bg,
.card__bg,
.sentence-word,
.quick-btn,
.category,
.game-cell,
